export interface ConnectorConfig {
  /** Airtable base ID (e.g., appXXXXXXXXXXXXXX) */
  baseId: string
  /** Airtable table ID or name */
  tableIdOrName: string
  /** Airtable personal access token (from env var AIRTABLE_PERSONAL_ACCESS_TOKEN) */
  accessToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface ShopifyOrderPaidPayload {
  id: number
  email: string
  total_price: string
  order_number?: number
  [key: string]: unknown
}

export interface HandleResult {
  createdRecordIds: string[]
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is ShopifyOrderPaidPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'number') {
    throw new Error('Missing required field: id (order ID)')
  }
  if (typeof p.email !== 'string') {
    throw new Error('Missing required field: email (customer email)')
  }
  if (typeof p.total_price !== 'string') {
    throw new Error('Missing required field: total_price (order total)')
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const order = payload as ShopifyOrderPaidPayload

  const url = `https://api.airtable.com/v0/${config.baseId}/${config.tableIdOrName}`
  const body = {
    records: [
      {
        fields: {
          'Order ID': order.id,
          'Customer Email': order.email,
          Total: order.total_price,
        },
      },
    ],
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Airtable API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const data = (await response.json()) as { records?: Array<{ id: string }> }
  const createdRecordIds = data.records?.map((r) => r.id) ?? []
  return { createdRecordIds }
}

