    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ShopifyOrderPaidPayload, config)
