      req.url === 'https://api.airtable.com/v0/appTestBase123/tblTestTable456'
        ? jsonResponse(TARGET_ENDPOINTS[0].response, 201)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 9876543210,
      email: 'test@example.com',
      total_price: '99.99',
    }

    const result = await handle(payload, config)

    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.airtable.com/v0/appTestBase123/tblTestTable456')
    expect(call.headers.get('authorization')).toBe('Bearer patTestToken789')
    expect(call.json).toEqual({
      records: [
        {
          fields: {
            'Order ID': 9876543210,
            'Customer Email': 'test@example.com',
            Total: '99.99',
          },
        },
      ],
    })
    expect(result.createdRecordIds).toEqual(['recABC123def456'])
  })

  it('throws on missing required field id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }

    const payload = { email: 'test@example.com', total_price: '10.00' }

    await expect(handle(payload as unknown as ShopifyOrderPaidPayload, config)).rejects.toThrow(
      'Missing required field: id (order ID)'
    )
  })

  it('throws on missing required field email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }

    const payload = { id: 123, total_price: '10.00' }

    await expect(handle(payload as unknown as ShopifyOrderPaidPayload, config)).rejects.toThrow(
      'Missing required field: email (customer email)'
    )
  })

  it('throws on missing required field total_price', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }

    const payload = { id: 123, email: 'test@example.com' }

    await expect(handle(payload as unknown as ShopifyOrderPaidPayload, config)).rejects.toThrow(
      'Missing required field: total_price (order total)'
    )
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'invalid-token',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 123,
      email: 'test@example.com',
      total_price: '10.00',
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Airtable API error: 401 Unauthorized for POST https://api.airtable.com/v0/appTestBase123/tblTestTable456'
    )
    expect(calls).toHaveLength(1)
  })

  it('returns empty array when response has no records', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = {
      baseId: 'appTestBase123',
      tableIdOrName: 'tblTestTable456',
      accessToken: 'patTestToken789',
      fetch,
    }

    const payload: ShopifyOrderPaidPayload = {
      id: 123,
      email: 'test@example.com',
      total_price: '10.00',
    }

    const result = await handle(payload, config)
    expect(result.createdRecordIds).toEqual([])
  })
})

